package akogen.fabric.v6;
import java.lang.reflect.*;import java.util.*;import com.google.gson.*;
public final class Names{
 public static ClassLoader loader;static JsonObject names;static Map<String,Method> cache=new HashMap<String,Method>();static final Map<Class<?>,Map<String,Field>> fields=new HashMap<Class<?>,Map<String,Field>>();
 public static Class<?> type(String n)throws Exception{String key=n.replace('.','/');if(names.getAsJsonObject("classes").has(key))n=names.getAsJsonObject("classes").get(key).getAsString().replace('/','.');return Class.forName(n,true,loader);}
 static List<String> aliases(String kind,String n){List<String> out=new ArrayList<String>();out.add(n);JsonObject o=names.getAsJsonObject(kind);if(o.has(n))for(JsonElement v:o.getAsJsonArray(n))out.add(v.getAsString());return out;}
 static int rank(Class<?> c){if(c==Byte.class||c==byte.class)return 0;if(c==Short.class||c==short.class)return 1;if(c==Integer.class||c==int.class)return 2;if(c==Long.class||c==long.class)return 3;if(c==Float.class||c==float.class)return 4;if(c==Double.class||c==double.class)return 5;return -1;}
 static int score(Class<?>[] types,Object[] args){if(types.length!=args.length)return -1;int sum=0;for(int i=0;i<types.length;i++){if(args[i]==null){if(types[i].isPrimitive())return -1;sum+=4;continue;}Class<?> a=args[i].getClass(),t=types[i];if(t==a)continue;if(t.isInstance(args[i])){sum++;continue;}if(t==boolean.class&&a==Boolean.class)continue;if(t.isPrimitive()&&rank(t)>=rank(a)&&rank(a)>=0){sum+=rank(t)-rank(a);continue;}return -1;}return sum;}
 public static Object call(Object target,String name,Object... args)throws Exception{Class<?> c=target instanceof Class?(Class<?>)target:target.getClass();String key=c.getName()+"#"+name;for(Object a:args)key+=":"+(a==null?"null":a.getClass().getName());Method best=cache.get(key);if(best==null){int min=999;List<String> choices=aliases("methods",name);for(Method m:c.getMethods()){if(!choices.contains(m.getName()))continue;if(target instanceof Class&&!Modifier.isStatic(m.getModifiers()))continue;int s=score(m.getParameterTypes(),args);if(s>=0&&s<min){min=s;best=m;}}if(best==null)throw new NoSuchMethodException(c.getName()+" "+name+"/"+args.length);best.setAccessible(true);cache.put(key,best);}try{return best.invoke(target instanceof Class?null:target,args);}catch(InvocationTargetException e){Throwable t=e.getCause();if(t instanceof Exception)throw (Exception)t;throw e;}}
 static Field resolveField(Class<?> c,String n)throws Exception{Map<String,Field> byName=fields.get(c);if(byName==null){byName=new HashMap<String,Field>();fields.put(c,byName);}Field f=byName.get(n);if(f!=null)return f;for(String name:aliases("fields",n))for(Class<?> p=c;p!=null;p=p.getSuperclass())try{f=p.getDeclaredField(name);f.setAccessible(true);byName.put(n,f);return f;}catch(NoSuchFieldException ignored){}throw new NoSuchFieldException(c.getName()+" "+n);}
 public static Object field(Object target,String n)throws Exception{Class<?> c=target instanceof Class?(Class<?>)target:target.getClass();return resolveField(c,n).get(target instanceof Class?null:target);}
 public static Object create(String n,Object...args)throws Exception{Class<?> c=type(n);Constructor<?> best=null;int min=999;for(Constructor<?> k:c.getDeclaredConstructors()){int s=score(k.getParameterTypes(),args);if(s>=0&&s<min){min=s;best=k;}}if(best==null)throw new NoSuchMethodException(c.getName()+" constructor");best.setAccessible(true);return best.newInstance(args);}
 public static void set(Object target,String n,Object value)throws Exception{resolveField(target.getClass(),n).set(target,value);}
 public static double number(Object o){return ((Number)o).doubleValue();}
}
